"""Offline setup translations; source keys and formatting tokens stay stable."""

_LANGUAGES = ("es", "pt-BR", "ru", "pl", "de", "fr", "tr", "ko", "ja", "zh-CN")
CATALOG = {}


def _add(source, translations):
    values = translations.split("|")
    if len(values) != len(_LANGUAGES):
        raise ValueError(f"Installer translation count differs: {source}")
    CATALOG[source] = dict(zip(_LANGUAGES, values))


